# -*- coding: utf-8 -*-
"""R84 B17 blind predictions writer. Appends segments; each segment asserts."""
import json, os

OUT = "/home/hatch/workspace/divination/benchmark/phase3/runs/round84/predictions"
os.makedirs(OUT, exist_ok=True)

def F(reason=""):
    return {"changed_main": False, "reserve_used": False, "disputed": False, "reason": reason}

def T(cm=False, ru=False, di=False, reason=""):
    return {"changed_main": cm, "reserve_used": ru, "disputed": di, "reason": reason}

def write(rec):
    assert set(rec.keys()) == {"case_id", "prediction_text", "basis", "confidence", "trigger"}, rec["case_id"]
    assert 0.0 <= rec["confidence"] <= 1.0
    assert set(rec["trigger"].keys()) == {"changed_main", "reserve_used", "disputed", "reason"}
    p = os.path.join(OUT, rec["case_id"] + ".json")
    assert not os.path.exists(p), "refuse overwrite: " + p
    with open(p, "w", encoding="utf-8") as f:
        json.dump(rec, f, ensure_ascii=False, indent=1)
    with open(p, encoding="utf-8") as f:
        back = json.load(f)
    assert back["case_id"] == rec["case_id"]
    print("wrote", rec["case_id"])

